VALUES (NULL, NULL, 19650, 'Section 8: Prejudice', 'Section 8: Prejudice', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3jdn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fqghpmcrsquvbb9mtrdz.jpg', 'On the battlefield, prejudice takes many forms, knows no boundaries, and drives all conflict. In the distant future, humanity will call on its most fearless defenders to confront an emerging threat determined to eradicate all human life as we know it. Section 8: Prejudice is a sci-fi first-person shooter with dynamic combat, where every decision – from customizing equipment to activating team based objectives – drastically impacts the battlefield.', 'https://www.igdb.com/games/section-8-prejudice', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.1, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
