VALUES (NULL, NULL, 132334, 'Diplomacy is Not an Option', 'Diplomacy is Not an Option', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co90jc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arj73.jpg', 'In the RTS-game “Diplomacy is Not an Option” you will become a medieval feudal lord in a midlife crisis. Due to your position you must constantly make hundreds of decisions a day related with city management and economic development. You are tired of this monotonous and, so it seems, meaningless existence. But things are about to change: hordes of bloodlusted enemies, swarms of scary monsters and crowds of rebellious peasants at any second can bring some life to your working schedule.', 'https://www.igdb.com/games/diplomacy-is-not-an-option', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
