VALUES (NULL, NULL, 373282, 'Tabletop Tavern', 'Tabletop Tavern', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaof1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4gcd.jpg', 'Total War meets Slay the Spire in a new RTS rougelike.

Dive into Tabletop Tavern, a real-time strategy roguelike where every battle is a roll of the dice—and every victory is earned. Command your mercenaries on a chaotic tabletop battlefield, recruit a wild roster of warriors, and forge your legacy against relentless goblin hordes. With infinite builds, brutal choices, and endless replayability, this is RTS chaos for roguelike fanatics.', 'https://www.igdb.com/games/tabletop-tavern', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
