VALUES (NULL, NULL, 252826, 'South of Midnight', 'South of Midnight', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8bot.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ft8.jpg', 'South of Midnight is a new action-adventure from Compulsion Games. Explore the mythos and confront mysterious creatures of the Deep South in this modern folktale while learning to weave an ancient power to surmount obstacles and face the pain haunting your hometown.', 'https://www.igdb.com/games/south-of-midnight', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.1, 0, 1.27, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
