VALUES (NULL, NULL, 1331, 'Limbo', 'Limbo', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qrs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6juz.jpg', 'Limbo is a black and white puzzle-platforming adventure. Players take the role of a young boy traveling through an eerie and treacherous world in an attempt to discover the fate of his sister.', 'https://www.igdb.com/games/limbo', '["PlayStation 3", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "PlayStation Vita", "Xbox 360", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 1.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
