VALUES (NULL, NULL, 75341, 'Wytchwood', 'Wytchwood', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27gm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkqe.jpg', 'Wytchwood is a crafting adventure game set in a land of gothic fables and fairytales. As the old witch of the woods, explore a strange countryside, collect magic ingredients, brew sorcerous spells, and pass judgement upon a capricious cast of characters.', 'https://www.igdb.com/games/wytchwood', '["Xbox Series X|S", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.0, 0, 1.06, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
