VALUES (NULL, NULL, 22395, 'Boundary', 'Boundary', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4uxi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar13a6.jpg', 'A multiplayer tactical space-based shooter that puts players in the role of a heavily armed astronauts in space engaging in fierce zero gravity firefights. Fully customizable loadouts, weapons and ammo types across 6 classes of Astronaut for players to choose from in multiple game modes.', 'https://www.igdb.com/games/boundary', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, NULL, 0, 9.22, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
