VALUES (NULL, NULL, 2033, 'Call of Duty: Ghosts', 'Call of Duty: Ghosts', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3b15.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar692.jpg', 'Call of Duty: Ghosts is a first-person shooter set in a near-future scenario where the United States has been devastated by an orbital weapons strike. The single-player campaign follows Logan Walker, a soldier fighting alongside an elite special operations unit called the Ghosts against the Federation of the Americas, a South American military superpower. Multiplayer introduces destructible map elements, new game modes such as Cranked and Blitz, and a Squads mode with AI-controlled teammates. The game also features Extinction, a four-player cooperative mode where players fight waves of alien creatures called Cryptids.', 'https://www.igdb.com/games/call-of-duty-ghosts', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Wii U", "Xbox 360", "Xbox One"]', NULL, 6.9, 0, 7.04, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
