VALUES (NULL, NULL, 1820, 'Dragon Quest IX: Sentinels of the Starry Skies', 'Dragon Quest IX: Sentinels of the Starry Skies', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wt9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ne2uunz9fsttvv2zxqml.jpg', 'In Dragon Quest IX: Sentinels of the Starry Skies, players begin their adventure as a city guardian who is sent to retrieve a sacred trees fruits, which have the power to grant wishes. Players travel the world, conquer fearsome monsters and unravel an epic storyline. During their journey, players will encounter mighty opponents in fast-paced battles, and also interact with a colorful cast of characters.', 'https://www.igdb.com/games/dragon-quest-ix-sentinels-of-the-starry-skies', '["Nintendo DS"]', NULL, 8.6, 0, 0.0, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
