VALUES (NULL, NULL, 118085, 'Adapt', 'Adapt', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4iaj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tap.jpg', 'To survive, you must guide your species through a constantly changing world. Compete with strange creatures for food and territory, and find your niche through careful evolutionary choices. The real question is not if you can survive, but for how long.', 'https://www.igdb.com/games/adapt', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 7.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
