VALUES (NULL, NULL, 63189, 'Close Combat: Cross of Iron', 'Close Combat: Cross of Iron', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3nbk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars6q.jpg', 'Close Combat: Cross of Iron is an enhanced remake of the critically acclaimed real time strategy game, Close Combat III: The Russian Front by Atomic Games. Playing as either the Germans or Russians, the game takes place during WWII on the Russian Front, where as a commander you must lead your troops through five years of brutal combat.', 'https://www.igdb.com/games/close-combat-cross-of-iron', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
