VALUES (NULL, NULL, 7584, 'Star Trek Online', 'Star Trek Online', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1o44.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arorc.jpg', 'Star Trek Online is a premier free-to-play MMORPG from Cryptic Studios and Arc Games set in the famous Star Trek universe. Don the official uniforms of the United Federation of Planets, the Klingon Empire, the Romulan Republic, or the Dominion. Adventure alongside over 40 Star Trek actors reprising their roles, including Kate Mulgrew as Katherine Janeway, Ethan Peck as Spock, and LeVar Burton as Geordi La Forge. Star Trek Online is completely free to play on PC, Xbox and Playstation.', 'https://www.igdb.com/games/star-trek-online', '["PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 6.6, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
