VALUES (NULL, NULL, 320137, 'Cronos: The New Dawn', 'Cronos: The New Dawn', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqq9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar35r1.jpg', 'Cronos: The New Dawn is a pulse-pounding, third-person survival horror game that throws you into the heart of a deadly struggle against overwhelming foes, all while uncovering the mysteries of a twisted time travel story.', 'https://www.igdb.com/games/cronos-the-new-dawn', '["Xbox Series X|S", "Linux", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.8, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
