VALUES (NULL, NULL, 179886, 'Neyasnoe', 'Neyasnoe', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co76tg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2gg3.jpg', 'A fragment of the game about a dude looking for meaning and reasons to live and not finding it; getting lost in the labyrinth of his own thoughts and ceasing to understand other people; smoking a lot and destroying himself.', 'https://www.igdb.com/games/neyasnoe', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.2, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
