VALUES (NULL, NULL, 133308, 'The Medium', 'The Medium', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cockn5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8h0.jpg', 'Discover a dark mystery only a medium can solve. Explore the real world and the spirit world at the same time. Use your psychic abilities to solve puzzles spanning both worlds, uncover deeply disturbing secrets, and survive encounters with The Maw - a monster born from an unspeakable tragedy. The Medium is a third-person psychological horror game that features patented dual-reality gameplay and an original soundtrack.', 'https://www.igdb.com/games/the-medium', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 7.3, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
