VALUES (NULL, NULL, 134502, 'Atom RPG: Trudograd', 'Atom RPG: Trudograd', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2spe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tcs.jpg', 'Atom RPG: Trudograd is a turn-based post-apocalyptic roleplaying game, which continues the story of Atom RPG as a stand-alone sequel/expansion, and follows the traditions set by classic cRPGs such as the early Fallout and Wasteland titles.', 'https://www.igdb.com/games/atom-rpg-trudograd', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
