VALUES (NULL, NULL, 376847, 'Z.A.T.O.: I Love the World and Everything In It', 'Z.A.T.O.: I Love the World and Everything In It', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coavot.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4nwb.jpg', 'USSR, 1986. A girl goes missing in the closed city of Vorkuta-5, yet not a soul seems to be concerned. Uncover the mystery behind her disappearance and transmit your signal to the universe.', 'https://www.igdb.com/games/z-dot-a-t-dot-o-i-love-the-world-and-everything-in-it', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.9, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
