VALUES (NULL, NULL, 123791, 'The Light Remake', 'The Light Remake', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2c7o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aro6g.jpg', 'There is only you, the abandoned remains of a former life and the flourishing nature that feels great in the absence of man. This world is both gloomy and empty, but so incredibly beautiful.', 'https://www.igdb.com/games/the-light-remake', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
