VALUES (NULL, NULL, 72176, 'Pocket Tanks', 'Pocket Tanks', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coah6p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7g0u.jpg', 'The fastest game of artillery you''ll ever play. Pocket Tanks is designed to be easy to learn, and fun to master. All the excitement of lobbing projectiles over a mound of dirt without all the complicated details found in most artillery games. Select your angle, power, and fire over 30 distinct weapons at your opponent. There is an innovative Weapon Shop to keep the game moving fast and a Target Practice mode for experimenting with all the weapons "no holds barred!"', 'https://www.igdb.com/games/pocket-tanks', '["Android", "PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 7.0, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
