VALUES (NULL, NULL, 654, 'Company of Heroes', 'Company of Heroes', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ht7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argi0.jpg', 'Command the company that changed the face of history! Battle your way across Europe as your troops make intuitive use of the terrain and buildings for cover and mount attacks on an equally intelligent enemy. Your Mission. Your Men. Your Decisions.', 'https://www.igdb.com/games/company-of-heroes', '["Android", "PC (Microsoft Windows)", "iOS"]', NULL, 9.0, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
