VALUES (NULL, NULL, 171757, 'Kaiju Wars', 'Kaiju Wars', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4p1i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar147l.jpg', 'Play out a Kaiju movie as the (hopelessly) outclassed military in this stylish 2D turn-based strategy game. Construct buildings and defend your city with cannon-fodder tanks, jets and more as the devastating kaiju grow in power with every attack.', 'https://www.igdb.com/games/kaiju-wars', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 7.8, 0, 10.05, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
