VALUES (NULL, NULL, 27117, 'Into the Breach', 'Into the Breach', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gjp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6fxo.jpg', 'The remnants of human civilization are threatened by gigantic creatures breeding beneath the earth. You must control powerful mechs from the future to hold off this alien threat. Each attempt to save the world presents a new randomly generated challenge in this turn-based strategy game from the makers of FTL.', 'https://www.igdb.com/games/into-the-breach', '["Google Stadia", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Nintendo Switch"]', NULL, 8.6, 0, 10.76, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
