VALUES (NULL, NULL, 647, 'Command & Conquer', 'Command & Conquer', 'game', 1995, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co88m7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xeskgryidexo1st73gjn.jpg', 'Experience the game that started it all! Enter a gritty, high-tech world and take advantage of electronic intelligence and covert surveillance to determine who reigns supreme. Join either the forces of the Global Defense Initiative (GDI) or the Brotherhood of Nod as you build bases, muster forces and dominate your enemies. All for the love of power. Play as the Brotherhood and obey the charismatic Kane’s every command or take control of GDI forces as they seek to save the world from Kane’s ambition. Gather Tiberium to produce tanks, infantry and more to decide the fate of the world.', 'https://www.igdb.com/games/command-conquer', '["PlayStation 3", "Nintendo 64", "PC (Microsoft Windows)", "Mac", "DOS", "Sega Saturn", "PlayStation", "PlayStation Portable"]', NULL, 8.4, 0, 9.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
