VALUES (NULL, NULL, 236547, 'Thronefall', 'Thronefall', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ydi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6n7m.jpg', 'A minimalist game about building and defending a little kingdom. Thronefall is a classic strategy game without unnecessary complexity, just some healthy hack-and-slay. Build up your base during the day, and defend it ‘til your last breath at night.', 'https://www.igdb.com/games/thronefall', '["Xbox Series X|S", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Nintendo Switch"]', NULL, 7.9, 0, 9.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
