VALUES (NULL, NULL, 115991, 'The Riftbreaker', 'The Riftbreaker', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1jna.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar56e.jpg', 'The Riftbreaker is a base-building, survival game with Action-RPG elements. You are an elite scientist/commando inside an advanced Mecha-Suit capable of dimensional rift travel. Hack & slash countless enemies. Build up your base, collect samples and research new inventions to survive.', 'https://www.igdb.com/games/the-riftbreaker', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.4, 0, 9.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
