VALUES (NULL, NULL, 7668, 'Iron Brigade', 'Iron Brigade', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j9c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1qks.jpg', 'Join The Mobile Trench Brigade and protect humanity from the evil Monovision menace in this Tower Defense Shooter from Tim Schafer''s Double Fine Productions. Use a combination of mobile firepower and stationary defenses to turn the tide of war in our favor. Customize your trench with thousands of possible loadouts. March side-by-side with allies from around the world as you fight your way through Europe, Africa, and the Pacific.', 'https://www.igdb.com/games/iron-brigade', '["PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.0, 0, 9.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
