VALUES (NULL, NULL, 14879, 'Attack on Titan', 'Attack on Titan', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4qqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sm1aonhssukfnsssetjn.jpg', 'Attack on Titan closely follows the riveting story line of Attack on Titan’s first season and focuses on the exploits of various key characters, putting the player in a position to relive the anime’s most shocking, courageous, and exhilarating moments. It revolves around the story of three young people who survive the destruction of their walled city district by enormous, man-eating Titans and eventually go on to join the Scout Regiment in order to protect humanity from this overpowering foe.', 'https://www.igdb.com/games/attack-on-titan', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation Vita", "Xbox One"]', NULL, 7.1, 0, 8.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
