VALUES (NULL, NULL, 466, 'Warhammer 40,000: Dawn of War II', 'Warhammer 40,000: Dawn of War II', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3lu2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3bgx.jpg', 'With a focus on fast-action RTS gameplay, Dawn of War II brings to life the science fiction universe of Warhammer 40,000 like never before. Experience the intimate brutality of battle as you play through your chosen race''s epic campaign.', 'https://www.igdb.com/games/warhammer-40-000-dawn-of-war-ii', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.0, 0, 8.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
