VALUES (NULL, NULL, 77880, 'Remote Control Dandy', 'Remote Control Dandy', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5rs9.jpg', NULL, 'A Japan-only Playstation game in which you play a little boy controlling a giant robot via remote control. Developed by Sandlot, who later developed the Earth Defense Force series, and had a direct sequel -- Remote Control Dandy SF -- on the PS2.', 'https://www.igdb.com/games/remote-control-dandy', '["PlayStation"]', NULL, NULL, 0, 8.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
