VALUES (NULL, NULL, 19619, 'Steambot Chronicles', 'Steambot Chronicles', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jjj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar50po.jpg', 'Steambot Chronicles is a 2005 action-adventure role-playing game developed and published by Irem Software Engineering in Japan for the PlayStation 2. It was later published by Atlus in North America and 505 Games in PAL regions. The game features a sandbox-style of steam-powered, mech-based gameplay.', 'https://www.igdb.com/games/steambot-chronicles', '["PlayStation 2"]', NULL, 8.3, 0, 7.52, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
