VALUES (NULL, NULL, 361822, 'Battlestar Galactica: Scattered Hopes', 'Battlestar Galactica: Scattered Hopes', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc1s0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5uqx.jpg', 'In Battlestar Galactica: Scattered Hopes, take command of a fleet escaping the annihilation of the Twelve Colonies. Manage crises on board as you prepare for the next encounter with the Cylon Fleet. Times are dire, and hard choices must be made. Your only hope: rejoin the Battlestar Galactica.', 'https://www.igdb.com/games/battlestar-galactica-scattered-hopes', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 8.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
