VALUES (NULL, NULL, 758, 'Independence War 2: Edge of Chaos', 'Independence War 2: Edge of Chaos', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24nz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/y2xvcdqkhgnwxewgrej4.jpg', 'Command four space vessels and a band of revolutionary pirates into an all-consuming battle against impossible odds, because there just isn''t enough Space for everyone!', 'https://www.igdb.com/games/independence-war-2-edge-of-chaos', '["PC (Microsoft Windows)"]', NULL, 7.1, 0, 9.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
