VALUES (NULL, NULL, 924, 'Wing Commander', 'Wing Commander', 'game', 1990, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2khm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5j9l.jpg', 'Gameplay consists of completing successive missions and overall cockpit performance affects gameplay: going above and beyond the call of duty results in medals, promotions in rank are awarded at regular intervals, and success or failure on certain critical missions decides the player''s plot progress, "winning" or "losing".', 'https://www.igdb.com/games/wing-commander', '["Amiga CD32", "PC (Microsoft Windows)", "Mac", "DOS", "FM Towns", "Amiga"]', NULL, 8.1, 0, 8.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
