VALUES (NULL, NULL, 110270, 'XO', 'XO', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2k9z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arifz.jpg', 'XO is a relentless, strategic fleet defense game blending real-time with pause, political intrigue and a punishing drive to survive. Take command of the last battleship, gather a fleet and try to unite five hostile factions in a desperate bid to save humanity from an unbeatable enemy.', 'https://www.igdb.com/games/xo', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.0, 0, 7.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
