VALUES (NULL, NULL, 750, 'Homeworld 2', 'Homeworld 2', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29zu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wqmlhxufjuzs1yscx9ae.jpg', 'Homeworld 2 is the third game in the Homeworld series. Although well-received and praised for its lavish graphics, Homeworld 2 did not receive the same level of acclaim as Homeworld 1 or Cataclysm. Patches and an active modding community has helped keep Homeworld 2 popular until its re-release by Gearbox Software in 2015.', 'https://www.igdb.com/games/homeworld-2', '["PC (Microsoft Windows)", "Mac"]', NULL, 8.0, 0, 9.51, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
