VALUES (NULL, NULL, 23527, 'Battlestar Galactica Online', 'Battlestar Galactica Online', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gsu3svw5tsui8lmvu2af.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ygfz5bgl3pknlo883d2a.jpg', 'Browser MMORPG based on the hit TV series. Jump into a Viper to blast Cylons, or join the inevitable machines piloting a Cylon Raider. Winner of several major awards, and a universe millions of players call home.', 'https://www.igdb.com/games/battlestar-galactica-online', '["Web browser"]', NULL, NULL, 0, 8.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
