VALUES (NULL, NULL, 7468, 'Tom Clancy''s EndWar', 'Tom Clancy''s EndWar', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yhv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6q56.jpg', 'In addition to traditional RTS controls, EndWar goes beyond other Real Time Strategy games by letting you use your own voice to control your units, offering you true control at the speed of thought.
Instead of using the traditional top-down view, EndWar employs a unique third-person camera that puts you in the heart of the battle, making the use of terrain and cover even more critical to achieving victory. Zoom in and out at will and watch the devastation unfold as hundreds of units engage the enemy on fully destructible battlefields.', 'https://www.igdb.com/games/tom-clancy-s-endwar', '["PlayStation 3", "PC (Microsoft Windows)", "PlayStation Portable", "Xbox 360", "Nintendo DS"]', NULL, 7.1, 0, 9.03, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
