VALUES (NULL, NULL, 10242, 'Blitzkrieg', 'Blitzkrieg', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nkt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvfn.jpg', 'Blitzkrieg is a real-time tactics computer game based on the events of World War II and is the first title in the Blitzkrieg (video game series). The game allows players to assume the role of commanding officer during the battles of World War II that occurred in Europe and North Africa. Each country has its respective historically correct military units. Similar to the Sudden Strike games Blitzkrieg focuses on battles rather than real-time strategy aspects like base building.', 'https://www.igdb.com/games/blitzkrieg', '["PC (Microsoft Windows)", "Mac"]', NULL, 7.2, 0, 9.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
