VALUES (NULL, NULL, 423854, 'Malignus', 'Malignus', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod5ek.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6t2i.jpg', 'A dungeon colony sim where you play the dungeon itself: its Boss, its minions and the beasts in its caves. Dig out halls, wire deadly traps, and raid the world above for treasure. Then hold your hoard against the heroes who come to take it back. Play alone or in 2–4 player co-op.', 'https://www.igdb.com/games/malignus', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 7.16, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
