VALUES (NULL, NULL, 9634, 'Endless Space', 'Endless Space', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wci.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armix.jpg', 'This galaxy is ancient, and its first intelligent life was the civilization we call the Endless. Long before our eyes gazed upon the stars they flew between them, though all that remains of this people is what we call Dust. A substance found scattered, or in forgotten temples, it once gave powers to admirals and galactic governors. The galaxy will belong to the faction that can take control of the Dust and uncover its secrets…', 'https://www.igdb.com/games/endless-space', '["PC (Microsoft Windows)"]', NULL, 7.4, 0, 8.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
