VALUES (NULL, NULL, 106803, 'Gloomhaven', 'Gloomhaven', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q8w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arprb.jpg', '"In Gloomhaven, you play as a team of mercenaries on their own personal quests to go conquer a world of gloomy and wicked decadence. Choose your group members wisely, because in the turmoil of battle you can only rely on your wits, skills and spells to fight your way through the putrid dungeons and forgotten ruins. In this rogue-like dungeon-crawling adaptation of the famous board game, you will journey through terrifying randomly generated dungeons, fight against increasingly horrific and powerful foes…or die trying. "', 'https://www.igdb.com/games/gloomhaven', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.0, 0, 9.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
