VALUES (NULL, NULL, 60212, 'Cogmind', 'Cogmind', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1udx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arke5.jpg', 'Cogmind is a sci-fi roguelike epic in which you play a robot building yourself from components found or salvaged from other robots. Explore a living, breathing world through turn-based tactical combat, or sneak, hack, and fly your way to victory.', 'https://www.igdb.com/games/cogmind', '["PC (Microsoft Windows)"]', NULL, 8.0, 0, 10.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
