VALUES (NULL, NULL, 24512, 'Ostriv', 'Ostriv', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20pt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arquy.jpg', 'Ostriv is a city-building game that puts you in a role of a governor of an 18th century Ukrainian town to challenge your creative skills and management abilities. 
 
Ostriv aims to raise the bar of city-building experience by adding a huge amount of possibilities and removing annoying limitations. It allows for truly organic town layouts without the grid and angle restrictions on a three-dimensional landscape. The goal is to make player''s creations to become alive and believable communities where real-life problems would arise, thus making the late game a new challenge rather than a repetitive chore.', 'https://www.igdb.com/games/ostriv', '["PC (Microsoft Windows)"]', NULL, 8.7, 0, 9.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
