VALUES (NULL, NULL, 27384, 'Graveyard Keeper', 'Graveyard Keeper', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1w53.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbsr.jpg', 'Graveyard Keeper is the most inaccurate medieval cemetery management sim of the year. Build & manage your own graveyard while finding shortcuts to cut costs, expand into entertainment with witch-burning festivals, and scare nearby villagers into attending church. This is a game of capitalism and doing whatever it takes to build a thriving business.', 'https://www.igdb.com/games/graveyard-keeper', '["PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.4, 0, 9.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
