VALUES (NULL, NULL, 19724, 'Bastard Bonds', 'Bastard Bonds', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3lzb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkvi.jpg', '"Bastard Bonds is a mature, fast-paced tactical RPG with high-end pixel art and in-depth character customization, including built-in sprite mod support. Featuring more than 200 in-game locations, more than 1000 character sprites, an all-original soundtrack, and 40+ hours of gameplay."', 'https://www.igdb.com/games/bastard-bonds', '["PC (Microsoft Windows)"]', NULL, 6.8, 0, 9.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
