VALUES (NULL, NULL, 34351, 'Twilight Struggle', 'Twilight Struggle', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rri.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjze.jpg', 'Twilight Struggle is a two-player game where players play as either the US or USSR during the Cold War. Using actual events from history, players must plan out their strategies in order to obtain world dominance. Play Twilight Struggle and change the course of history.', 'https://www.igdb.com/games/twilight-struggle', '["Android", "PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 8.0, 0, 8.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
