VALUES (NULL, NULL, 164213, 'Destroyer: The U-Boat Hunter', 'Destroyer: The U-Boat Hunter', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6hrj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar24b7.jpg', 'Destroyer: the U-Boat Hunter is an interactive war thriller which seamlessly blends tactical WW2 anti-submarine warfare simulation with a gripping storyline. Take command of a meticulously reconstructed Fletcher-class destroyer and lead your crew against nazi U-boats in the Battle of the Atlantic!', 'https://www.igdb.com/games/destroyer-the-u-boat-hunter', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 8.03, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
