VALUES (NULL, NULL, 354951, 'Cranked', 'Cranked', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4mv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar660k.jpg', 'Chase the top of the leaderboards in Cranked and experience the raw thrill of downhill mountain bike racing. It’s fast, responsive, and grounded -- we''re chasing what it really feels like to ride. Easy to pick up, impossible to put down, and packed with virtually endless skill depth.', 'https://www.igdb.com/games/cranked', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 1.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
