VALUES (NULL, NULL, 19554, 'Steep', 'Steep', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod3sc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ra.jpg', 'Ride a massive open world of the Alps and Alaska, where the powder is always fresh and the run never ends.Defy and master the world’s most epic mountains on skis, wingsuit, snowboard, and in paraglide. Go solo or drop in side by side with other players. Record and share the most insane stunts ever captured, then challenge the world to beat your best tricks, ride your custom lines, and relive your most epic wipeouts.', 'https://www.igdb.com/games/steep', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 7.5, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
