VALUES (NULL, NULL, 271109, 'Dust Front RTS', 'Dust Front RTS', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coayei.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2kla.jpg', 'Dust Front is a real-time strategy game that blends classic RTS mechanics with grand strategy elements. Players engage in military operations across barren battlefields using varied tactics from mass infantry deployment to strategic bombing raids. The game features a non-linear campaign where players choose their path through different military scenarios and strategic decisions.', 'https://www.igdb.com/games/dust-front-rts', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.02, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
