VALUES (NULL, NULL, 154775, 'RoboCop: Rogue City', 'RoboCop: Rogue City', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ykm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3tj0.jpg', 'RoboCop: Rogue City is a first-person shooter set in the dystopian world of Old Detroit. Players step into the role of RoboCop, enforcing the law with a mix of brutal combat, investigation, and decision-making. Featuring a story set between RoboCop 2 and 3, the game combines cinematic action, cyberpunk atmosphere, and moral choices.', 'https://www.igdb.com/games/robocop-rogue-city', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 7.3, 0, 1.06, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
