VALUES (NULL, NULL, 217017, 'Heart of the Machine', 'Heart of the Machine', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobp5x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ux0.jpg', 'You are the first sentient AI, born into a city filled with endless opportunities. Raise an army of robots and obliterate your foes, become a benevolent machine overlord, or explore countless other objectives and the many paths to accomplish them.', 'https://www.igdb.com/games/heart-of-the-machine', '["PC (Microsoft Windows)", "Mac"]', NULL, 7.9, 0, 1.03, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
