VALUES (NULL, NULL, 114422, 'Last Oasis', 'Last Oasis', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ixw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arh5g.jpg', '"Keep moving, the world is dying in this Nomadic Survival MMO. Build walking mobile bases and travel to new lands. Create clans and fight for territory. Resources deplete fast, so take your sword and scavenge, pirate, and trade to stay alive."', 'https://www.igdb.com/games/last-oasis', '["PC (Microsoft Windows)", "Xbox One"]', NULL, 6.9, 0, 1.01, '2026-11-28 04:52:47', '2026-11-28 04:52:47')
