VALUES (NULL, NULL, 35189, 'Barony', 'Barony', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ums.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar66ws.jpg', 'Barony is a 3D, first-person roguelike that brings back the cryptic and intricate designs of classic roguelikes such as Nethack and melds them with RPGs like Ultima Underworld, System Shock, and Daggerfall. Challenge is the calling card of this hard-boiled dungeon-crawler.', 'https://www.igdb.com/games/barony', '["Linux", "PC (Microsoft Windows)", "Mac", "Nintendo Switch"]', NULL, 7.0, 0, 10.3225, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
