VALUES (NULL, NULL, 8796, 'Tales of Maj''Eyal', 'Tales of Maj''Eyal', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2iqa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1996.jpg', 'Tales of Maj''Eyal is a roguelike RPG, featuring tactical turn-based combat and advanced character building. Play as one of many unique races and classes in the lore-filled world of Eyal, exploring random dungeons, facing challenging battles, and developing characters with your own tailored mix of abilities and powers.', 'https://www.igdb.com/games/tales-of-majeyal', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.8, 0, 12.2775, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
