VALUES (NULL, NULL, 28649, 'Stoneshard', 'Stoneshard', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xdb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars7z.jpg', 'Set off on a perilous journey across the procedurally generated world, while various followers flock under your banners. You will have to face not only hundreds of foes but also pain, hunger, fear and internal disputes. Put an end to the protracted war or plunge the country into even deeper chaos.', 'https://www.igdb.com/games/stoneshard', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.7, 0, 8.11, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
