VALUES (NULL, NULL, 52006, 'Noita', 'Noita', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qp1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7dm.jpg', 'Noita is a magical action roguelite set in a world where every pixel is physically simulated. Fight, explore, melt, burn, freeze and evaporate your way through the procedurally generated world using spells you''ve created yourself. Explore a variety of environments ranging from coal mines to freezing wastelands while delving deeper in search for unknown mysteries.', 'https://www.igdb.com/games/noita', '["PC (Microsoft Windows)"]', NULL, 7.9, 0, 1.29714285714285715e+01, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
