VALUES (NULL, NULL, 109117, 'Volcanoids', 'Volcanoids', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co69f0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar55u.jpg', 'A base-building open-world survival shooter that replaces the typical base with a giant drill. Alone or with friends, explore an island plagued by eruptions, upgrade your drill, and battle robots to uncover what''s been hiding beneath the surface.', 'https://www.igdb.com/games/volcanoids', '["Linux", "PC (Microsoft Windows)"]', NULL, 6.0, 0, 8.70333333333333314e+00, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
