VALUES (NULL, NULL, 187096, 'Forever Skies', 'Forever Skies', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co92li.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6eb5.jpg', 'Forever Skies is a first-person action survival game. Return to Earth destroyed by an ecological disaster, fly a high-tech airship, expand, rebuild and repair it. Scavenge resources to survive, face the dangers of the surface as you will hunt for viral pathogens to cure a mysterious illness.', 'https://www.igdb.com/games/forever-skies', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.0, 0, 9.22666666666666657e+00, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
