VALUES (NULL, NULL, 252846, 'Sand: Raiders Of Sophie', 'Sand: Raiders Of Sophie', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc93o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6329.jpg', 'In an alternate 1910, scavenge the sands of Sophie in towering Tramplers. Build your highly customizable walking base. Squad up or go solo. Gather loot, weapons, precious artifacts. Clash with other players in a brutal procedurally generated desert forged by history and chaos.', 'https://www.igdb.com/games/sand-raiders-of-sophie', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.0, 0, 5.02, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
