VALUES (NULL, NULL, 570, 'Prototype', 'Prototype', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ql2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzyq.jpg', 'Prototype is the first of two games, and lets the user take control of Alex Mercer as he fights to stop the viral outbreak known as BLACKLIGHT throughout Manhattan. Alex is himself infected by the virus, which has given him special, mutant, abilities that will evolve with time and aid him in stopping the virus.', 'https://www.igdb.com/games/prototype', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.6, 0, 6.11333333333333328e+00, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
