VALUES (NULL, NULL, 2903, 'Warframe', 'Warframe', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocytd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6598.jpg', 'Warframe situates players as members of the Tenno race, newly awoken after years of cryo-sleep into a solar system at war. Reborn into a corrupt era, the Tenno are sought by the oppressive Grineer Empire for annihilation. Warframe armor is the key to overthrowing the Grineer by providing players with unique offensive and defensive powers to explore, upgrade and master during purpose-driven radical raids.', 'https://www.igdb.com/games/warframe', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.4, 0, 1.86730769230769233e+01, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
