VALUES (NULL, NULL, 216947, 'Quasimorph', 'Quasimorph', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod5j1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2byo.jpg', 'Take on a role of a hardened PMC fighter in a dark turn-based extraction RPG. Engage in unforgiving combat, manage your ship and pile up the bodies of your clones to unravel the dark mystery behind threat to all life.', 'https://www.igdb.com/games/quasimorph', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.6, 0, 11.622, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
