VALUES (NULL, NULL, 16657, 'UnderRail', 'UnderRail', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kp4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4x3g.jpg', 'Underrail is an old school turn-based isometric indie role playing game that focuses on exploration and combat. The player takes control of one of the denizens of such a station-state whose life is about to become all that much more interesting and dangerous, as our protagonist is caught midst the conflicting factions of the Underrail as the violently struggle to survive in the harsh underground environment.', 'https://www.igdb.com/games/underrail', '["PC (Microsoft Windows)"]', NULL, 7.6, 0, 6.02, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
