VALUES (NULL, NULL, 252827, 'Star Wars Outlaws', 'Star Wars Outlaws', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9nh7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar69b6.jpg', 'Experience the first-ever open world Star Wars game, set between the events of The Empire Strikes Back and Return of the Jedi. Explore distinct planets across the galaxy, both iconic and new. Risk it all as Kay Vess, an emerging scoundrel seeking freedom and the means to start a new life, along with her companion Nix. Fight, steal, and outwit your way through the galaxy’s crime syndicates as you join the galaxy’s most wanted.', 'https://www.igdb.com/games/star-wars-outlaws', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.7, 0, 7.57, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
