VALUES (NULL, NULL, 66396, 'Space Station 13', 'Space Station 13', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1of6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpc51.jpg', 'Space Station 13 (ss13) is a multiplayer role-playing game. Originally created by one person named Exadv1, development has been continued by members of the fan base.', 'https://www.igdb.com/games/space-station-13', '["PC (Microsoft Windows)"]', NULL, 9.4, 0, 5.51500000000000056e+00, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
