VALUES (NULL, NULL, 187246, 'Warno', 'Warno', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4cu2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cq7.jpg', 'Realistic, immersive, breathtaking. Warno is the ultimate World War III battle simulator. A Cold War turns decisively hot as you command hundreds of units on a beautiful and brutal battlefield. Outsmart, outfight, and lead your forces to total victory.', 'https://www.igdb.com/games/warno', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 9.6, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
