VALUES (NULL, NULL, 147187, 'Broken Arrow', 'Broken Arrow', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaav2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ary0e.jpg', 'Broken Arrow is a large-scale real-time modern warfare tactics game. The base game features both the American and Russian factions, more than 100 units and multiple deck specialisations per nation. Broken Arrow brings the genre to a whole new level by combining the complexity of a joint-forces wargame with the typical real-time tactics action-packed gameplay.', 'https://www.igdb.com/games/broken-arrow', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 5.74666666666666614e+00, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
