VALUES (NULL, NULL, 1039, 'The Legend of Zelda: Ocarina of Time 3D', 'The Legend of Zelda: Ocarina of Time 3D', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co600u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/otz3syek3fcly3orwmco.jpg', 'The Legend of Zelda: Ocarina of Time 3D is a remake of Ocarina of Time with more up-to-date graphics, streamlined UI and different additional game modes. Most textures are significantly more detailed, and many models are more faithful to the game''s concept and promotional art. In addition, the frame rate has been increased to 30 FPS compared to the original''s 20 FPS.', 'https://www.igdb.com/games/the-legend-of-zelda-ocarina-of-time-3d', '["Nintendo 3DS"]', NULL, 9.1, 0, 2.105, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
