VALUES (NULL, NULL, 204354, 'Aliens: Dark Descent', 'Aliens: Dark Descent', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6liu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1pbn.jpg', 'Drop into the gripping journey of Aliens: Dark Descent, a squad-based, single-player action game in the iconic Alien franchise. Lead your soldiers in real-time to stop a new and terrifying kind of Xenomorph outbreak on Planet Lethe.', 'https://www.igdb.com/games/aliens-dark-descent', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.1, 0, 5.86333333333333328e+00, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
