VALUES (NULL, NULL, 247621, 'Silica', 'Silica', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6i48.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2aex.jpg', 'Silica is a crossover of FPS and RTS where up to 3 factions battle for control over the planet of Baltarus. Lead from above as commander, or experience the action first-hand, either alone, or with friends. Join one of two human armies, or hunt them down as the territorial aliens.', 'https://www.igdb.com/games/silica', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 3.01, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
