VALUES (NULL, NULL, 2025, 'Mount & Blade: Warband', 'Mount & Blade: Warband', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y8y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar75l.jpg', 'In a land torn asunder by incessant warfare, it is time to assemble your own band of hardened warriors and enter the fray. Lead your men into battle, expand your realm, and claim the ultimate prize: the throne of Calradia!', 'https://www.igdb.com/games/mount-blade-warband', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 7.7, 0, 6.455, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
