VALUES (NULL, NULL, 7046, 'Factorio', 'Factorio', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tfy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5tzh.jpg', 'You will be mining resources, researching technologies, building infrastructure, automating production and fighting enemies. Use your imagination to design your factory, combine simple elements into ingenious structures, apply management skills to keep it working and finally protect it from the creatures who don''t really like you.', 'https://www.igdb.com/games/factorio', '["Linux", "Nintendo Switch 2", "PC (Microsoft Windows)", "Mac", "Nintendo Switch"]', NULL, 8.6, 0, 6.02333333333333342e+00, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
