VALUES (NULL, NULL, 9495, 'Squad', 'Squad', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaasd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arh44.jpg', 'Squad is a large scale combined arms multiplayer first-person shooter emphasizing combat realism through communication, team play, emphasizing strong squad cohesion mechanics as well as larger-scale coordination, tactics, and planning. It features 20 large open maps, vehicle-based combined arms gameplay, and player-constructed bases to create a heart-thumping, visceral gaming experience with split-second decision-making in real-world scale firefights.', 'https://www.igdb.com/games/squad', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 8.085, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
