VALUES (NULL, NULL, 37016, 'Metro Exodus', 'Metro Exodus', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaroh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3s93.jpg', 'Metro Exodus is an epic, story-driven first person shooter from 4A Games that blends deadly combat and stealth with exploration and survival horror in one of the most immersive game worlds ever created. Explore the Russian wilderness across vast, non-linear levels and follow a thrilling story-line that spans an entire year through spring, summer and autumn to the depths of nuclear winter. Inspired by the novels of Dmitry Glukhovsky, Metro Exodus continues Artyom’s story in the greatest Metro adventure yet.', 'https://www.igdb.com/games/metro-exodus', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.3, 0, 8.322, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
