VALUES (NULL, NULL, 127346, 'Sons of the Forest', 'Sons of the Forest', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobyfc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1mx9.jpg', 'Sent to find a missing billionaire on a remote island, you find yourself in a cannibal-infested hellscape. Craft, build, and struggle to survive, alone or with friends, in this terrifying new open-world survival horror simulator.', 'https://www.igdb.com/games/sons-of-the-forest', '["PC (Microsoft Windows)"]', NULL, 7.4, 0, 8.214, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
