VALUES (NULL, NULL, 204634, 'The Alters', 'The Alters', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaaju.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ra3.jpg', 'Explore an emotional sci-fi game with a unique blend of survival, adventure, and base-building elements. Help Jan Dolski, the sole survivor of an ill-fated space expedition, create alternative versions of himself to escape a hostile planet and tackle personal turmoils with this unconventional crew.', 'https://www.igdb.com/games/the-alters', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.3, 0, 3.04, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
