VALUES (NULL, NULL, 19562, 'Resident Evil 7: Biohazard', 'Resident Evil 7: Biohazard', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobtwh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vh0.jpg', 'Resident Evil 7: Biohazard is the first game of the Resident Evil series to switch from 3rd-person to fully 1st-person perspective. A complete refresh of gameplay systems simultaneously propels the survival horror experience to another level. It is as much horror as it is survival, boosting up scare elements and minimizing downright shooting action. The game allows use of Sony''s PSVR Headset to play in VR mode.', 'https://www.igdb.com/games/resident-evil-7-biohazard', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PlayStation VR", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.5, 0, 2.11, '2026-11-19 20:56:22', '2026-11-28 04:52:47')
