VALUES (NULL, NULL, 25208, 'Dungeon Rats', 'Dungeon Rats', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ttz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4li8.jpg', '“Dungeon Rats, named after the 7th Heavy Armored Division of the Imperial Guards, is a turn-based, party-based dungeon crawler set in the Age of Decadence world. It''s an RPG focused almost exclusively on combat for players who like turn-based combat in general and AoD combat in particular, so if you want to fight your way out of a prison mine (or die trying) you''ve come to the right place.”', 'https://www.igdb.com/games/dungeon-rats', '["PC (Microsoft Windows)"]', NULL, 6.9, 0, 6.01, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
