VALUES (NULL, NULL, 749, 'Homeworld', 'Homeworld', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc6i8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ilnzntjuwfenzaywtxlc.jpg', 'Homeworld is a 3D real-time strategy game set in space and focusing on the conflict between the Kushan, who are attempting to locate their long-lost homeworld, and the Taiidan Empire which is trying to destroy them.', 'https://www.igdb.com/games/homeworld', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.7, 0, 10.48, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
