VALUES (NULL, NULL, 2949, 'Killing Floor', 'Killing Floor', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sn9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars0k.jpg', 'Killing Floor is a Co-op Survival Horror FPS set in the devastated cities and countryside of England after a series of cloning experiments for the military goes horribly wrong. You and your friends are members of the military dropped into these locations with a simple mission: Survive long enough to cleanse the area of the failed experiments!', 'https://www.igdb.com/games/killing-floor', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.1, 0, 6.0166666666666666e+00, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
