VALUES (NULL, NULL, 251741, 'Ships at Sea', 'Ships at Sea', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co88la.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2c33.jpg', 'Experience the thrill of navigating a wide range of ships. Immerse yourself in various career paths such as service, cargo and commercial fishing, as you explore the breathtaking open world of Norway´s Lofoten Islands with its stunning scenery. The ocean is within your reach!', 'https://www.igdb.com/games/ships-at-sea', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 2.02, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
