VALUES (NULL, NULL, 101440, 'S.T.A.L.K.E.R. 2: Heart of Chornobyl', 'S.T.A.L.K.E.R. 2: Heart of Chornobyl', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocqoz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar36lb.jpg', 'S.T.A.L.K.E.R. 2: Heart of Chornobyl is the unforgiving FPS survival adventure in a dark science-fiction open world. Scavenge for gear and resources, hunt for wonders, make hard decisions to survive and pave the path through the Chornobyl Anomalous Zone.', 'https://www.igdb.com/games/stalker-2-heart-of-chornobyl', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.5, 0, 9.44571428571428484e+00, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
