VALUES (NULL, NULL, 217518, 'Sea Power: Naval Combat in the Missile Age', 'Sea Power: Naval Combat in the Missile Age', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8pqs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1vdd.jpg', 'From the lead designer of Cold Waters, Sea Power lets you control NATO and Warsaw Pact forces in modern naval conflict campaigns. Use your advanced naval weaponry and sensors to respect rules of engagement and defeat the enemy forces in a tense fight for initiative and air/naval supremacy.', 'https://www.igdb.com/games/sea-power-naval-combat-in-the-missile-age', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 11.54, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
