VALUES (NULL, NULL, 31551, 'Final Fantasy XVI', 'Final Fantasy XVI', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobd9i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2dl2.jpg', 'A single-player action RPG set in a high-fantasy world where warring nations and powerful summoned Eikons shape political intrigue and personal vengeance. Players control Clive, a former shield bearer whose life is upended by tragedy. Engage in fast-paced, tactical real-time combat that blends heavy weapons, Eikon-driven abilities, and cinematic set pieces.
Deeply narrative-driven, the game emphasizes character development, expansive locales to explore, and dramatic boss encounters while offering layered combat customization through combos, parries, and skill upgrades.', 'https://www.igdb.com/games/final-fantasy-xvi', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.7, 0, 6.27, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
