VALUES (NULL, NULL, 231, 'Half-Life', 'Half-Life', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc2ea.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpo4.jpg', 'Half-Life is a 1998 first-person shooter (FPS) game developed by Valve Corporation and published by Sierra Studios for Windows. It was Valve''s debut product and the first game in the Half-Life series. The player assumes the role of Gordon Freeman, a theoretical physicist who must escape from the Black Mesa Research Facility after it is overrun by aliens following a disastrous scientific experiment. Its gameplay consists of diverse combat, exploration and puzzles.', 'https://www.igdb.com/games/half-life', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.4, 0, 5.79666666666666685e+00, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
