VALUES (NULL, NULL, 1910, 'Outlast', 'Outlast', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yat.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar75m.jpg', 'Hell is an experiment you can''t survive in Outlast, a first-person survival horror game developed by veterans of some of the biggest game franchises in history. As investigative journalist Miles Upshur, explore Mount Massive Asylum and try to survive long enough to discover its terrible secret... if you dare.', 'https://www.igdb.com/games/outlast', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.7, 0, 2.01, '2026-11-21 21:29:28', '2026-11-28 04:52:47')
