VALUES (NULL, NULL, 2021, 'Mount & Blade', 'Mount & Blade', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2egl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar65u6.jpg', 'Mount & Blade is an immersive medieval action/tactics game taking place in a fictitious land named Calradia. Enriched with RPG elements, Mount & Blade offers a captivating environment, beautifully detailed with hundreds of castles, towns, and villages to explore.', 'https://www.igdb.com/games/mount-blade', '["PC (Microsoft Windows)"]', NULL, 6.9, 0, 8.27666666666666728e+00, '2026-11-23 03:29:46', '2026-11-28 04:52:47')
