VALUES (NULL, NULL, 30002, 'Lobotomy Corporation', 'Lobotomy Corporation', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26qi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arq8u.jpg', 'Monster Management Rogue-Lite Simulation game inspired by the monsters from game and movies such as SCP Foundation, Cabin in the woods and Warehouse 13. One disaster will cause another, and it will lead everything into chaos. Manage and Survive.', 'https://www.igdb.com/games/lobotomy-corporation', '["PC (Microsoft Windows)"]', NULL, 7.8, 0, 1.20233333333333334e+01, '2026-11-23 03:29:46', '2026-11-28 04:52:47')
