VALUES (NULL, NULL, 185962, 'Nebulous: Fleet Command', 'Nebulous: Fleet Command', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ozf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1hso.jpg', 'Take command of your hand-tailored fleet of space warships and use realistic radar, electronic warfare, advanced movement controls in 3D space, and precision targeting to outmaneuver and outwit your opponents in a simulation-heavy tactical space game like no other.', 'https://www.igdb.com/games/nebulous-fleet-command', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.07175000000000011e+01, '2026-11-23 15:29:50', '2026-11-28 04:52:47')
