VALUES (NULL, NULL, 219570, 'Task Force Admiral: Vol.1 - American Carrier Battles', 'Task Force Admiral: Vol.1 - American Carrier Battles', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9f8s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1w76.jpg', 'Experience the thrill of leading American aircraft carriers to victory in this innovative full 3D command simulation wargame set in the Pacific in 1942. First-person or God’s eye, you lead your fleet and planes right from the center of the battle.', 'https://www.igdb.com/games/task-force-admiral-vol-dot-1-american-carrier-battles', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 9.53, '2026-11-23 15:29:50', '2026-11-28 04:52:47')
