VALUES (NULL, NULL, 13361, 'Brigador', 'Brigador', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wbu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6hn.jpg', 'Brigador is an isometric vehicle action game set in completely destructible environments. Highly difficult without being unfair. Lush revivalist graphic style reminds you of what 90''s games would look like now. Huge variety of playable vehicles and weapons, deep tactics and high skill ceiling with custom map support all contribute to a game built to be played and enjoyed for a long time.', 'https://www.igdb.com/games/brigador', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.7, 0, 5.76333333333333364e+00, '2026-11-24 04:24:23', '2026-11-28 04:52:47')
