VALUES (NULL, NULL, 421, 'Final Fantasy IX', 'Final Fantasy IX', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2unc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3og1.jpg', 'Final Fantasy IX is the ninth main installment in the FF series. The title is a return to the series''s roots, with gameplay features and references to the past games featuring throughout, as well as a medieval fantasy setting and cartoonish art style as a break from the sci-fi slant style of Final Fantasy VII and Final Fantasy VIII.', 'https://www.igdb.com/games/final-fantasy-ix', '["PlayStation 3", "PlayStation", "PlayStation Portable"]', NULL, 8.6, 0, 6.04, '2026-11-26 23:52:17', '2026-11-28 04:52:47')
