VALUES (NULL, NULL, 2262, 'Gothic II', 'Gothic II', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25ag.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dbdzjo180b3q4n7s3w6s.jpg', 'Gothic II is a role-playing video game and the sequel to Gothic, by the German developer Piranha Bytes. It was first released on November 29, 2002 in Germany, with North America following almost one year later on October 28, 2003. The game was published by JoWooD Entertainment and Atari.', 'https://www.igdb.com/games/gothic-ii', '["PC (Microsoft Windows)"]', NULL, 8.3, 0, 2.075, '2026-11-26 23:52:17', '2026-11-28 04:52:47')
