VALUES (NULL, NULL, 1040, 'Alice: Madness Returns', 'Alice: Madness Returns', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n91.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/id9pd5yegrh25a3yd7bi.jpg', 'Return to Wonderland and experience an all new nightmare as Alice fights to regain her sanity as she fights for the truth behind her past. Can Alice save Wonderland - and herself - from the madness that consumes them both?', 'https://www.igdb.com/games/alice-madness-returns', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.3, 0, 2.085, '2026-11-26 23:52:17', '2026-11-28 04:52:47')
