VALUES (NULL, NULL, 54651, 'You Are Empty', 'You Are Empty', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7797.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hqjyela3zgmtaxclhuaq.jpg', 'You Are Empty is a first-person shooter video game based in a fictionalized postwar Soviet Union. The game begins with the protagonist waking up in a ruined hospital, and it soon becomes clear that the populace has been afflicted by mutation and madness. He then must battle to stay alive and unravel the mystery.', 'https://www.igdb.com/games/you-are-empty', '["PC (Microsoft Windows)"]', NULL, 6.5, 0, 5.52, '2026-11-27 20:45:57', '2026-11-28 04:52:47')
