VALUES (NULL, NULL, 239786, 'Hail to the Rainbow', 'Hail to the Rainbow', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod2tg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6qgz.jpg', 'The story of a lonely young man named Ignat, who survives in the dangerous and gloomy world of post-apocalyptic cyberpunk. You have to face the trials of a new reality and plunge into the secrets of the surrounding chaos.', 'https://www.igdb.com/games/hail-to-the-rainbow', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.2, 0, 5.52, '2026-11-27 20:45:57', '2026-11-28 04:52:47')
