VALUES (NULL, NULL, 131760, 'Library of Ruina', 'Library of Ruina', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8z9s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armnf.jpg', '"May you find your book in this place." Combat between the guests and the librarians breaks out as if it were on a stage. Defeated guests turn into books, and the Library grows onward. And eventually, get your hands on… The one singular, perfect book.', 'https://www.igdb.com/games/library-of-ruina', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.7, 0, 11.02, '2026-11-27 20:45:57', '2026-11-28 04:52:47')
