VALUES (NULL, NULL, 35934, 'Airships: Conquer the Skies', 'Airships: Conquer the Skies', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hugqfysoswzwvcwlgjls.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1a80.jpg', 'Design steampunk pixel airships out of functional modules and conquer the skies!', 'https://www.igdb.com/games/airships-conquer-the-skies', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.0, 0, 6.625, '2026-11-27 20:45:57', '2026-11-28 04:52:47')
